const priorPackageBody=bodyFor;
Object.assign(subtitles,{'Konsultasi VIP':'Review, evaluasi, dan optimasi bersama praktisi.','TikTok Shop collaboration':'Dukungan strategi dan operasional TikTok Shop.','TikTok One collaboration':'Kolaborasi konten dan kreator untuk kampanye.','Affiliate or Creator Support':'Dukungan affiliate atau kreator UGC sesuai paket.','TTMS Review':'Tinjauan TikTok Market Scope.'});
const vipCadence={'Konsultasi VIP Level 2':'1 kali per bulan','Konsultasi VIP Level 3':'setiap 2 minggu','Konsultasi VIP Level 4':'setiap minggu','Konsultasi VIP Level 5':'setiap minggu'};
function vipDetails(id){const selected=Number(id.match(/Level (\d)/)?.[1])||2,current=getQualifiedLevel(),cadence=['','','1 kali per bulan','setiap 2 minggu','setiap minggu','setiap minggu'];return `Frekuensi Level ${selected}: ${cadence[selected]}. ${current>=2?`Pada Level ${current} saat ini: ${cadence[current]}.`:'Level saat ini belum memenuhi syarat konsultasi.'} Frekuensi mengikuti level tertinggi dan tidak dijumlahkan antarlevel.`}
Object.keys(vipCadence).forEach(id=>subtitles[id]='Review, evaluasi, dan optimasi bersama praktisi.');
bodyFor=function(id){if(id==='Konsultasi VIP'||vipCadence[id])return `<p>Review, evaluasi, dan optimasi untuk kebutuhan brand.</p>${chip(['TikTok Ads','TikTok Shop','TikTok One'])}${card('Konsultasi VIP',`<p>${vipDetails(id)} Jadwal dan pelaksanaan mengikuti ketentuan tim Buzzo.</p><p>Contoh formulir: jadwal dan data belum dikirim atau disimpan.</p><fieldset ${getQualifiedLevel()<Number(id.match(/Level (\d)/)?.[1]||2)?'disabled':''}><label>Tanggal konsultasi · WIB<input type="date"></label><label>Waktu · WIB<select><option>10:00</option><option>11:00</option><option>13:00</option><option>14:00</option><option>15:00</option></select></label><label>Tujuan dan kendala utama<textarea></textarea></label></fieldset>`)} `;if(id==='TikTok Shop collaboration')return `<p>Dukungan kolaborasi untuk pengelolaan TikTok Shop.</p>${card('Yang termasuk',`<ul><li>Strategi manajemen toko</li><li>Review operasional</li><li>Optimasi GMV Max</li></ul><p>Mulai Level 3.</p>`)}`;if(id==='TikTok One collaboration')return `<p>Dukungan kolaborasi untuk konten dan kreator di TikTok One.</p>${card('Yang termasuk',`<ul><li>Pembuatan dashboard</li><li>Konsultasi dan review brief kreator</li><li>Optimasi Spark Ads</li></ul><p>Mulai Level 3.</p>`)}`;if(id==='Affiliate or Creator Support')return `<p>Pilih salah satu bentuk dukungan sesuai ketentuan paket.</p>${card('Affiliate atau Creator Support',`<ul><li>Level 4: 70 affiliator atau 7 UGC kreator</li><li>Level 5: 150 affiliator atau 15 UGC kreator</li></ul><p>Pilih salah satu bentuk dukungan sesuai level yang tercapai.</p>`)}`;if(id==='TTMS Review')return `<p>Tinjauan TikTok Market Scope untuk kebutuhan brand.</p>${card('TTMS Review',`<p>Benefit pada paket Level 4 dan 5.</p>`)}`;return priorPackageBody(id)};
